<template><div class="wrap"><div class="page-head"><h1>Latest tipster picks</h1><p class="muted">Browse published predictions and compare tipster performance.</p></div><div class="toolbar"><input v-model="search" placeholder="Search fixture, league or tipster…"/><select v-model="status"><option value="">All picks</option><option value="published">Published</option><option value="won">Won</option><option value="lost">Lost</option></select></div><div class="grid3"><PickCard v-for="p in filtered" :key="p._id" :pick="p" @play="play"/></div><div v-if="!filtered.length" class="empty">No predictions found.</div><div class="locked" style="margin:35px 0"><div><b>Want to play a tipster pick?</b><p>Create a free BraTips account. Browsing is public; playing picks requires sign-in.</p></div><RouterLink class="btn" to="/signup">Create account</RouterLink></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {RouterLink,useRouter} from 'vue-router';import {api} from '../services/api';import PickCard from '../components/PickCard.vue';const data=ref<any[]>([]),search=ref(''),status=ref(''),router=useRouter();const filtered=computed(()=>data.value.filter(p=>(!status.value||p.status===status.value)&&(!search.value||`${p.fixture} ${p.league} ${p.tipsterId?.name}`.toLowerCase().includes(search.value.toLowerCase()))));function play(){router.push('/login')}onMounted(async()=>{try{data.value=(await api.get('/predictions?limit=100')).data}catch{}})</script>
